import{_ as e,c as t,o as i,a2 as a}from"./chunks/framework.gSKzFT2J.js";const m=JSON.parse('{"title":"Git et GitHub - Gestion des Branches","description":"","frontmatter":{},"headers":[],"relativePath":"fr/github/branch.md","filePath":"fr/github/branch.md"}'),r={name:"fr/github/branch.md"},n=a('<h1 id="git-et-github-gestion-des-branches" tabindex="-1">Git et GitHub - Gestion des Branches <a class="header-anchor" href="#git-et-github-gestion-des-branches" aria-label="Permalink to &quot;Git et GitHub - Gestion des Branches&quot;">​</a></h1><h2 id="creer-une-nouvelle-branche-sur-github" tabindex="-1">Créer une Nouvelle Branche sur GitHub <a class="header-anchor" href="#creer-une-nouvelle-branche-sur-github" aria-label="Permalink to &quot;Créer une Nouvelle Branche sur GitHub&quot;">​</a></h2><p>Sur GitHub, accédez à votre dépôt et cliquez sur le bouton de la branche actuelle (par défaut &quot;main&quot; ou &quot;master&quot;).</p><p>Là, vous pouvez créer une nouvelle branche :</p><ol><li>Tapez un nom descriptif pour la branche.</li><li>Cliquez sur <strong>Créer une branche</strong>.</li></ol><p>La nouvelle branche est maintenant créée et active. Vous pouvez vérifier sur quelle branche vous travaillez en regardant le bouton des branches. Par exemple, si votre nouvelle branche s&#39;appelle <strong>html-skeleton</strong>, ce nom apparaîtra à la place de &quot;main&quot;.</p><h3 id="verification-de-la-nouvelle-branche" tabindex="-1">Vérification de la Nouvelle Branche <a class="header-anchor" href="#verification-de-la-nouvelle-branche" aria-label="Permalink to &quot;Vérification de la Nouvelle Branche&quot;">​</a></h3><p>Une fois la branche créée, vous pouvez commencer à travailler sur un fichier existant dans cette branche.</p><ol><li>Cliquez sur le fichier <strong>index.html</strong> (ou tout autre fichier pertinent).</li><li>Commencez à l&#39;éditer directement sur GitHub.</li></ol><h3 id="previsualisation-et-validation-des-modifications" tabindex="-1">Prévisualisation et Validation des Modifications <a class="header-anchor" href="#previsualisation-et-validation-des-modifications" aria-label="Permalink to &quot;Prévisualisation et Validation des Modifications&quot;">​</a></h3><p>Après avoir modifié le fichier :</p><ol><li>Cliquez sur l&#39;onglet <strong>Preview changes</strong> pour voir les modifications mises en évidence.</li><li>Vérifiez que tout est correct.</li><li>Ajoutez un commentaire expliquant les changements effectués.</li><li>Cliquez sur <strong>Commit changes</strong> pour enregistrer les modifications dans cette branche.</li></ol><p>Vous avez maintenant une nouvelle branche sur GitHub avec des modifications enregistrées ! 🎉</p><p>Dans le prochain chapitre, nous verrons comment gérer les fusions et les Pull Requests sur GitHub.</p>',14),o=[n];function s(l,u,c,h,d,b){return i(),t("div",null,o)}const v=e(r,[["render",s]]);export{m as __pageData,v as default};
